INSERT INTO public.products (id, name, slug, description, price, "comparePrice", stock, images, specs, "isNew", "isFeatured", "isActive", "createdAt", "updatedAt", "categoryId", "brandId") VALUES
('cmrhi0bax000d6od67c20t3br', 'Plancha de Gypsum Regular 1/2" 1.22x2.44m', 'plancha-gypsum-regular-122x244', 'Plancha de gypsum regular de 1/2" (12.7mm) para cielo raso y divisiones interiores. Borde rebajado para juntas reforzadas.', 12.90, NULL, 80, ARRAY['https://images.unsplash.com/photo-1589939705384-5185137a7f0f?w=600','https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=600'], '{"Borde":"Rebajado (tapered edge)","Espesor":"12.7 mm (1/2\")","Peso aprox":"29.5 kg","Dimensiones":"1.22 x 2.44 m","Resistencia al fuego":"Clase A (ASTM C36)"}', false, true, true, '2026-07-12 07:55:05.913', '2026-07-12 07:55:05.913', 'cmrhi0a9y00006od6bq86wuju', 'cmrhi0b24000a6od6ti9ddx7t'),
('cmrhi0be1000e6od6e39uru8x', 'Plancha de Gypsum Resistente a Humedad RH 1.22x2.44m', 'plancha-gypsum-resistente-humedad', 'Plancha de gypsum con núcleo hidrofugado y forro tratado contra humedad. Ideal para baños, cocinas y sótanos.', 16.50, NULL, 45, ARRAY['https://images.unsplash.com/photo-1584622650111-993a426fbf0a?w=600'], '{"Color":"Verde","Espesor":"12.7 mm (1/2\")","Dimensiones":"1.22 x 2.44 m","Tratamiento":"Hidrofugado en núcleo y forro","Uso recomendado":"Baños, cocinas, áreas húmedas"}', true, true, true, '2026-07-12 07:55:06.025', '2026-07-12 07:55:06.025', 'cmrhi0a9y00006od6bq86wuju', 'cmrhi0aza00096od6f0e9ucug'),
('cmrhi0bgu000f6od660wz40hp', 'Panel WPC para Pared 20cm x 3m', 'panel-wpc-pared-20cm', 'Panel de WPC (Wood Plastic Composite) para revestimiento de paredes. Sistema de instalación oculta con clips. Resistente a UV y humedad.', 22.00, NULL, 35, ARRAY['https://images.unsplash.com/photo-1618219908412-a29a1bb7b86e?w=600'], '{"Ancho":"20 cm","Color":"Gris oscuro / Teak","Largo":"3 m","Acabado":"Textura madera cepillada","Espesor":"10 mm","Material":"WPC (60% fibra madera + 40% PVC)"}', false, true, true, '2026-07-12 07:55:06.126', '2026-07-12 07:55:06.126', 'cmrhi0acw00016od6hz66fa7n', 'cmrhi0b4v000b6od67529ssaq'),
('cmrhi0bjq000g6od6gqh90t6j', 'Perfil WPC para Cielo Raso 3m', 'perfil-wpc-cielo-raso', 'Perfil liviano de WPC para cielos rasos exteriores e interiores. Resistente a la intemperie, no se oxida ni se pudre.', 14.50, NULL, 50, ARRAY['https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=600'], '{"Uso":"Cielo raso exterior e interior","Ancho":"10 cm","Largo":"3 m","Espesor":"8 mm","Material":"WPC","Carga máxima":"15 kg/m (suspensión)"}', true, false, true, '2026-07-12 07:55:06.23', '2026-07-12 07:55:06.23', 'cmrhi0acw00016od6hz66fa7n', 'cmrhi0b4v000b6od67529ssaq'),
('cmrhi0bmm000h6od63rsq6u51', 'Lámina de Mármol PVC Decorativo 1.22x2.44m', 'lamina-marmol-pvc-decorativo', 'Lámina decorativa de PVC con impresión de alto relieve efecto mármol. Para revestimiento de paredes, columnas y muebles.', 35.00, NULL, 20, ARRAY['https://images.unsplash.com/photo-1600585154526-990dced4db0d?w=600'], '{"Acabado":"Brillante UV","Colores":"Blanco Carrara / Negro Marquina / Beige Travertino","Espesor":"3.5 mm","Material":"PVC rígido","Dimensiones":"1.22 x 2.44 m"}', true, true, true, '2026-07-12 07:55:06.334', '2026-07-12 07:55:06.334', 'cmrhi0afn00026od6n4usvepi', 'cmrhi0b7q000c6od6lccb8q6g'),
('cmrhi0bpj000i6od6xcldj8lv', 'Panel PVC Efecto Mármol para Pared 60cm x 2.44m', 'panel-pvc-efecto-marmol', 'Panel ranurado de PVC con diseño marmolado para revestimiento de paredes. Instalación rápida con adhesivo o perfil H.', 28.50, NULL, 25, ARRAY['https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=600'], '{"Acabado":"Mate / Satinado","Espesor":"8 mm","Material":"PVC compuesto","Ancho útil":"58.5 cm (con empalme)","Dimensiones":"0.60 x 2.44 m"}', true, false, true, '2026-07-12 07:55:06.439', '2026-07-12 07:55:06.439', 'cmrhi0afn00026od6n4usvepi', 'cmrhi0b7q000c6od6lccb8q6g'),
('cmrhi0bsb000j6od64xsruh4p', 'Perfil Metálico Canal Listón para Cielo Raso 3m', 'perfil-canal-liston-cielo-raso', 'Perfil metálico galvanizado en forma de canal listón para estructura de cielo raso suspendido. Para instalación de gypsum o paneles.', 4.80, NULL, 120, ARRAY['https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=600'], '{"Peso":"0.45 kg/m","Tipo":"Canal listón (hat channel)","Longitud":"3 m","Material":"Acero galvanizado calibre 26","Dimensiones":"25 x 40 mm"}', false, true, true, '2026-07-12 07:55:06.539', '2026-07-12 07:55:06.539', 'cmrhi0aif00036od6p7p40vio', 'cmrhi0b7q000c6od6lccb8q6g'),
('cmrhi0bv5000k6od6xjoypd9e', 'Suspensión y Anclaje para Cielo Raso (caja x 100)', 'suspension-anclaje-cielo-raso', 'Kit de suspensión regulable para cielo raso suspendido. Incluye alambre galvanizado, anclajes de expansión y conectores rápidos.', 18.50, NULL, 30, ARRAY['https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=600'], '{"Tipo":"Suspensión regulable","Incluye":"Alambre, anclaje expansivo, conector rápido","Material":"Acero galvanizado","Presentación":"Caja x 100 unidades","Longitud máxima":"1.5 m (regulable)","Capacidad de carga":"25 kg por punto"}', false, false, true, '2026-07-12 07:55:06.641', '2026-07-12 07:55:06.641', 'cmrhi0aif00036od6p7p40vio', 'cmrhi0b7q000c6od6lccb8q6g'),
('cmrhi0by3000l6od6hfnhaupa', 'Moldura de Poliestireno Lisa 2m', 'moldura-poliestireno-lisa-2m', 'Moldura lisa de poliestireno expandido de alta densidad para decoración de cielos rasos y paredes. Liviana y fácil de instalar con adhesivo.', 3.50, NULL, 200, ARRAY['https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=600'], '{"Alto":"3 cm","Ancho":"5 cm","Largo":"2 m","Acabado":"Liso (listo para pintar)","Material":"Poliestireno expandido de alta densidad","Instalación":"Adhesivo especial para molduras"}', false, true, true, '2026-07-12 07:55:06.747', '2026-07-12 07:55:06.747', 'cmrhi0al600046od6eccgwhqf', 'cmrhi0aza00096od6f0e9ucug'),
('cmrhi0c3r000n6od62gn1nl9m', 'Piso Flotante Laminado 8mm Roble (caja 2.13m2)', 'piso-flotante-laminado-8mm', 'Piso laminado de 8mm con sistema click AC4. Lámina decorativa Roble Europeo, resistente a rayones y manchas.', 22.50, NULL, 40, ARRAY['https://images.unsplash.com/photo-1581858726788-75bc0f6a952d?w=600'], '{"Acabado":"Roble Europeo mate","Espesor":"8 mm","Sistema":"Click (sin pegamento)","Garantía":"15 años residencial","m2 por caja":"2.13","Clasificación":"AC4 (alto tráfico residencial)"}', false, true, true, '2026-07-12 07:55:06.951', '2026-07-12 07:55:06.951', 'cmrhi0ao200056od6drw1t0jn', 'cmrhi0b24000a6od6ti9ddx7t'),
('cmrhi0c6l000o6od6o41s7idz', 'Piso Flotante SPC Roble Blanco 5mm (caja 2.45m2)', 'piso-flotante-spc-resistente', 'Piso vinílico SPC (Stone Plastic Composite) 100% impermeable. Núcleo rígido de piedra-cal compuesto, ideal para baños y cocinas.', 27.90, NULL, 35, ARRAY['https://images.unsplash.com/photo-1581858726788-75bc0f6a952d?w=600'], '{"Espesor":"5 mm (capa uso +0.5mm)","Sistema":"Click rígido","Material":"SPC (Stone Plastic Composite)","Garantía":"Lifetime residencial","m2 por caja":"2.45","Impermeable al agua":"Sí (24h sin daño)"}', true, true, true, '2026-07-12 07:55:07.053', '2026-07-12 07:55:07.053', 'cmrhi0ao200056od6drw1t0jn', 'cmrhi0b24000a6od6ti9ddx7t'),
('cmrhi0c9j000p6od6b653o334', 'Tira LED para Cielo Raso 5m 3000K/6500K', 'tira-led-cielo-raso-5m', 'Tira LED flexible para iluminación perimetral en cielos rasos y molduras. Temperatura de color ajustable, auto-adhesiva.', 11.50, NULL, 60, ARRAY['https://images.unsplash.com/photo-1550985616-10810253b84d?w=600'], '{"Largo":"5 m","Incluye":"Control remoto + adaptador 12V","Potencia":"24W","Vida util":"30,000 h","Flujo luminoso":"600 lm/m","Temperatura color":"3000K/4000K/6500K (ajustable)"}', true, false, true, '2026-07-12 07:55:07.159', '2026-07-12 07:55:07.159', 'cmrhi0aqv00066od66hv6ziqj', 'cmrhi0b7q000c6od6lccb8q6g'),
('cmrhi0cch000q6od65sc83ja5', 'Spot LED Empotrable para Gypsum 12W', 'spot-led-empotrable-gypsum', 'Spot LED redondo empotrable para cielo raso de gypsum. Corte de 10cm, luz blanca neutra 4000K. Incluye driver.', 8.90, NULL, 80, ARRAY['https://images.unsplash.com/photo-1497366216548-37526070297c?w=600'], '{"Incluye":"Driver LED","Ángulo":"120°","Potencia":"12W","Vida util":"25,000 h","Corte en placa":"10 cm de diámetro","Flujo luminoso":"1080 lm","Temperatura color":"4000K (neutro)"}', false, true, true, '2026-07-12 07:55:07.265', '2026-07-12 07:55:07.265', 'cmrhi0aqv00066od66hv6ziqj', 'cmrhi0b7q000c6od6lccb8q6g'),
('cmrhi0cf8000r6od6ud8o7hpi', 'Duela de PVC para Pared 20cm x 2.8m', 'duela-pvc-pared-20cm', 'Duela de PVC para revestimiento de paredes. Sistema de instalación oculta, imitación madera natural. Resistente a la humedad.', 12.80, NULL, 55, ARRAY['https://images.unsplash.com/photo-1533090161767-e6ffed986c88?w=600'], '{"Uso":"Paredes interiores","Ancho":"20 cm","Largo":"2.80 m","Acabado":"Roble Natural / Nogal","Espesor":"8 mm","Material":"PVC rígido","Instalación":"Clip oculto (machimbrado)"}', false, true, true, '2026-07-12 07:55:07.364', '2026-07-12 07:55:07.364', 'cmrhi0ato00076od6rfl04sv8', 'cmrhi0b4v000b6od67529ssaq'),
('cmrhi0ci1000s6od69cfx46cg', 'Duela de PVC para Techo 20cm x 2.8m', 'duela-pvc-techo-20cm', 'Duela de PVC liviana para cielos rasos exteriores e interiores. Resistente a UV, no se deforma con el calor ni la humedad.', 14.20, NULL, 45, ARRAY['https://images.unsplash.com/photo-1533090161767-e6ffed986c88?w=600'], '{"Uso":"Techos y cielos rasos","Ancho":"20 cm","Largo":"2.80 m","Acabado":"Blanco / Roble claro","Espesor":"6 mm","Material":"PVC rígido con estabilizador UV","Resistencia UV":"Sí"}', true, false, true, '2026-07-12 07:55:07.465', '2026-07-12 07:55:07.465', 'cmrhi0ato00076od6rfl04sv8', 'cmrhi0b4v000b6od67529ssaq'),
('cmrhi0ckt000t6od6oor072lb', 'Clavos para Gypsum (caja x 1000)', 'clavos-gypsum-caja', 'Clavos de acero electrosoldado con cabeza de sombrero para fijación de planchas de gypsum a perfiles metálicos.', 8.50, NULL, 40, ARRAY['https://images.unsplash.com/photo-1586864387789-628af9feed72?w=600'], '{"Uso":"Fijación de gypsum a perfiles metálicos","Cabeza":"Sombrero (8 mm diámetro)","Acabado":"Galvanizado","Longitud":"1\" (25 mm)","Material":"Acero electrosoldado","Presentación":"Caja x 1000 unidades"}', false, true, true, '2026-07-12 07:55:07.565', '2026-07-12 07:55:07.565', 'cmrhi0awg00086od6qxo7gxzu', 'cmrhi0b24000a6od6ti9ddx7t'),
('cmrhi0cqc000v6od6wjbjlpb4', 'Cinta de Papel para Juntas de Gypsum (rollo 150m)', 'cinta-papel-juntas-gypsum', 'Cinta de papel perforado para refuerzo de juntas entre planchas de gypsum. Fibra de vidrio longitudinal para alta resistencia a la tracción.', 6.90, NULL, 25, ARRAY['https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=600'], '{"Uso":"Juntas de gypsum y paneles de yeso","Ancho":"50 mm","Largo":"150 m (rollo)","Material":"Papel kraft perforado con fibra de vidrio","Resistencia a tracción":"≥ 40 N/cm"}', false, false, true, '2026-07-12 07:55:07.764', '2026-07-12 07:55:07.764', 'cmrhi0awg00086od6qxo7gxzu', 'cmrhi0aza00096od6f0e9ucug'),
('cmrhi0ct7000w6od663cqavcn', 'Masilla para Juntas de Gypsum (balde 5kg)', 'masilla-juntas-gypsum-5kg', 'Pasta para juntas de gypsum lista para usar. Secado rápido, mínimo encogimiento. Para el sellado y acabado de uniones entre planchas.', 14.90, NULL, 20, ARRAY['https://images.unsplash.com/photo-1562322140-8baeececf3df?w=600'], '{"Uso":"Juntas y acabados de gypsum","Tipo":"Pasta lista para usar","Color":"Blanco","Rendimiento":"~15 m2 por balde","Presentación":"Balde x 5 kg","Tiempo de secado":"60-90 min"}', false, false, true, '2026-07-12 07:55:07.866', '2026-07-12 07:55:07.866', 'cmrhi0awg00086od6qxo7gxzu', 'cmrhi0aza00096od6f0e9ucug'),
('cmt9ga3f90005x8d6hnemgz69', 'paul zaruma lopez', 'paul-zaruma-lopez', 'es para el test', 12.00, 34.00, 12, ARRAY['https://res.cloudinary.com/dxkmtbde/image/upload/v1787709825/basictech/products/jot8vi0cj848xvqjofbp.jpg'], '{}', true, true, true, '2026-08-26 02:03:57.703', '2026-08-26 02:08:31.895', 'cmt9dk1mi0002x8d6xajbyzcw', 'cmt9djuah0001x8d6h6dkz6e4'),
